import{_ as e,a as o}from"./chunks/logitech-f710.B7l_xlAJ.js";import{_ as s,o as t,c as i,a5 as l}from"./chunks/framework.BjM_ivYE.js";const m=JSON.parse('{"title":"개발자 가이드","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/developers-guide.md","filePath":"ko/software/developers-guide.md","lastUpdated":1790672017000}'),n={name:"ko/software/developers-guide.md"};function r(d,a,h,c,p,u){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="개발자-가이드" tabindex="-1">개발자 가이드 <a class="header-anchor" href="#개발자-가이드" aria-label="Permalink to &quot;개발자 가이드&quot;">​</a></h1><h2 id="소개" tabindex="-1">소개 <a class="header-anchor" href="#소개" aria-label="Permalink to &quot;소개&quot;">​</a></h2><p><strong>RBQ 시뮬레이션, 명령 및 배포/업데이트 매뉴얼에 오신 것을 환영합니다</strong></p><p>이 매뉴얼은 RBQ 로봇을 <strong>시뮬레이션</strong>하고 명령을 보내며, 실제 로봇에 직접 개발한 알고리즘을 <strong>배포</strong>하는 과정을 종합적으로 설명합니다.</p><h2 id="개발자를-위한-시뮬레이터와-운용-앱" tabindex="-1">개발자를 위한 시뮬레이터와 운용 앱 <a class="header-anchor" href="#개발자를-위한-시뮬레이터와-운용-앱" aria-label="Permalink to &quot;개발자를 위한 시뮬레이터와 운용 앱&quot;">​</a></h2><ul><li>RBQ 로봇은 <strong>MuJoCo</strong>를 사용해 정밀하게 시뮬레이션할 수 있습니다. 📝 <em>시뮬레이션 환경 &quot;playground&quot;는 다음 파일을 편집하여 수정할 수 있습니다:</em> <code>resources/model/rbq_environment.xml</code></li><li>로봇에 명령을 보내고 상태를 보는 일은 <strong>RBQ</strong> 앱으로 합니다. 실제 로봇에 쓰는 앱과 같은 앱이라, 시뮬레이터에서 익힌 절차가 실기에서 그대로 통합니다. <ul><li>로봇 상태와 센서 상태를 보여 주고, 터치·게임패드·키보드 입력을 받습니다.</li><li><strong><a href="/RBQ/ko/manual/downloads/">다운로드</a></strong> 페이지에서 받을 수 있습니다. 앱 전체 설명은 <a href="/RBQ/ko/manual/gui/introduction.html">RBQ 앱</a>에 있습니다.</li></ul></li></ul><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>이 저장소에는 PC 에서 도는 제어 GUI 가 들어 있지 않습니다. 예전 버전에는 정비용 <code>bin/GUI</code> 가 함께 들어 있었지만 더는 배포하지 않으며, 이 가이드의 모든 작업은 <strong>RBQ</strong> 앱으로 대신합니다.</p></div></div><h2 id="설치" tabindex="-1">설치 <a class="header-anchor" href="#설치" aria-label="Permalink to &quot;설치&quot;">​</a></h2><ul><li>이 섹션에서는 RBQ 로봇 시뮬레이션 및 개발 환경을 처음부터 설치하고 구성하는 방법을 설명합니다.</li></ul><h3 id="시스템-요구사항" tabindex="-1">시스템 요구사항 <a class="header-anchor" href="#시스템-요구사항" aria-label="Permalink to &quot;시스템 요구사항&quot;">​</a></h3><p>원활한 시뮬레이션 및 개발 환경 구동을 위해 다음 사양을 권장합니다:</p><ul><li><p>운영 체제: Ubuntu 22.04 (x86) <img src="'+e+'" alt="Ubuntu 22.04"></p></li><li><p>최소 PC 사양:</p><ul><li>CPU: Intel Core i7 12세대</li><li>RAM: 16 GB</li><li>저장 공간: 25 GB</li></ul></li><li><p>제어 장치</p><ul><li>키보드: W, A, S, D, Q, E 키와 방향키</li><li>조이스틱: Logitech Wireless Gamepad F710 (권장)</li></ul><p><img src="'+o+`" alt="Logitech Wireless Gamepad F710"></p></li></ul><h3 id="_1-rbq-저장소-다운로드" tabindex="-1">1. RBQ 저장소 다운로드 <a class="header-anchor" href="#_1-rbq-저장소-다운로드" aria-label="Permalink to &quot;1. RBQ 저장소 다운로드&quot;">​</a></h3><ul><li>아래 명령어로 저장소를 클론하세요:</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RainbowRobotics/RBQ.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ</span></span></code></pre></div><blockquote><p>모든 스크립트, 바이너리, SDK 코드는 <code>RBQ/</code> 아래에 있습니다. 모든 명령어는 이 디렉토리에서 실행하세요.</p></blockquote><blockquote><p><strong>참고:</strong> 사전 빌드된 바이너리는 <code>bin-x86_64/</code>(arm64는 <code>bin-aarch64/</code>)에 들어 있으므로 별도 빌드 단계는 필요하지 않습니다.</p></blockquote><h2 id="▶-시뮬레이션" tabindex="-1">▶ 시뮬레이션 <a class="header-anchor" href="#▶-시뮬레이션" aria-label="Permalink to &quot;▶ 시뮬레이션&quot;">​</a></h2><ul><li>시뮬레이터는 도커 안에서 실행됩니다. 도커 외에는 설치할 것이 없고, 도커가 없으면 스크립트가 설치를 제안합니다. 처음 실행할 때 이미지를 만드느라 몇 분 걸립니다. <a href="/RBQ/ko/software/simulator/mujoco.html">MuJoCo</a>를 참조하세요.</li><li>아래 스크립트로 <strong>RBQ 제어 모듈과 MuJoCo 시뮬레이터</strong>를 한 번에 실행합니다.</li></ul><p><strong>참고:</strong> <em><code>인자:</code></em></p><ul><li><code>--help</code> : 도움말 메시지를 출력하고 종료합니다.</li><li><code>--vision</code> : 비전 모듈을 함께 실행합니다 (예: 비전 센서, 계단 오르기 활성화).</li><li><code>--no-gui</code> : PC 쪽 GUI 를 건너뜁니다. 배포되는 저장소에는 GUI 가 없으므로 이 인자를 붙이십시오.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-gui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span></span></code></pre></div><ul><li>이 터미널에서 계속 실행되며, Ctrl-C 로 멈춥니다. 이 PC 에서 도커에 <code>sudo</code> 가 필요하면 비밀번호를 묻습니다. 입력하면 계속 진행됩니다.</li></ul><h3 id="초기화-시뮬레이션-로봇-연결-및-시작" tabindex="-1">초기화 - 시뮬레이션 로봇 연결 및 시작 <a class="header-anchor" href="#초기화-시뮬레이션-로봇-연결-및-시작" aria-label="Permalink to &quot;초기화 - 시뮬레이션 로봇 연결 및 시작&quot;">​</a></h3><p>시뮬레이터를 띄운 <strong>그 PC 에서</strong> RBQ 데스크탑 앱을 켭니다. 주변에 로봇망이 없으면 앱이 이 PC 의 MuJoCo 시뮬레이터를 스스로 찾아 붙습니다 — <a href="/RBQ/ko/manual/gui/connection.html">연결</a>을 참고하세요.</p><ol><li>허브에서 <strong>컨트롤</strong>을 눌러 제어 홈을 엽니다.</li><li>초록색 <strong>자동 기동</strong> 버튼을 누르고, 창에서 <strong>자동 기동</strong>을 눌러 시퀀스가 <strong>완료</strong>로 바뀔 때까지 기다린 뒤 <strong>닫기</strong>를 누릅니다.</li><li>모션 카드의 <code>STAND</code> 를 누릅니다. 로봇이 일어서고, 이후 명령을 받을 준비가 됩니다.</li></ol><ul><li>📝 <em>직전 자세에 따라 일어서는 데 1초쯤 걸릴 수 있습니다.</em></li></ul><h3 id="로봇-조종하기" tabindex="-1">로봇 조종하기 <a class="header-anchor" href="#로봇-조종하기" aria-label="Permalink to &quot;로봇 조종하기&quot;">​</a></h3><p>모션 카드에 <code>SIT</code>, <code>STAND</code>, <code>WALK</code>, <code>STAIRS</code> 가 있고, 점선 <strong>모션</strong> 버튼을 누르면 <code>Wave</code>·<code>Run</code> 이 들어 있는 전체 그리드가 열립니다. 조이스틱이 무엇을 하는지는 지금 어떤 모션인지에 따라 달라집니다 — 서 있으면 자세를 다듬고, 걸으면 로봇을 몹니다.</p><p><strong>→ <a href="/RBQ/ko/manual/gui/motion-commands.html">모션 명령</a></strong> 에 게이트별 축 표가 있고, <strong><a href="/RBQ/ko/manual/gui/control-home.html">제어 홈</a></strong> 에 PC 키보드 조종을 포함한 나머지 화면 설명이 있습니다.</p><h2 id="실제-로봇" tabindex="-1">실제 로봇 <a class="header-anchor" href="#실제-로봇" aria-label="Permalink to &quot;실제 로봇&quot;">​</a></h2><p>이 섹션에서는 <strong>실제 RBQ 로봇</strong> 작동 방법을 설명합니다.</p><p>📖 <em>상세한 작동 절차는 <a href="/RBQ/ko/guides/common/initial-pose.html">작동 가이드</a>를 참고하세요</em></p><h3 id="_1-로봇에-연결하기" tabindex="-1">1. 로봇에 연결하기 <a class="header-anchor" href="#_1-로봇에-연결하기" aria-label="Permalink to &quot;1. 로봇에 연결하기&quot;">​</a></h3><ul><li>PC를 로봇 Wi-Fi에 연결합니다. 📝 <em>Wi-Fi SSID: <code>RBQ_xxxx</code>.</em></li></ul><h3 id="_2-앱에서-로봇-제어-시작하기" tabindex="-1">2. 앱에서 로봇 제어 시작하기 <a class="header-anchor" href="#_2-앱에서-로봇-제어-시작하기" aria-label="Permalink to &quot;2. 앱에서 로봇 제어 시작하기&quot;">​</a></h3><p><strong>RBQ</strong> 앱을 켜고 로봇 목록에서 로봇을 고릅니다 — <a href="/RBQ/ko/manual/gui/connection.html">연결</a> 참고. 로봇과 통신이 시작되면 상태줄이 <code>연결됨</code> 과 경로를 표시합니다.</p><ul><li><strong>컨트롤</strong>을 눌러 제어 홈을 엽니다.</li><li><strong>자동 기동</strong>을 누르고, 창에서 <strong>자동 기동</strong>을 눌러 <strong>완료</strong>가 뜰 때까지 기다립니다. 이제 로봇이 활성화되어 조작할 준비가 됐습니다.</li></ul><h3 id="_3-명령은-시뮬레이션과-동일합니다" tabindex="-1">3. 명령은 시뮬레이션과 동일합니다 <a class="header-anchor" href="#_3-명령은-시뮬레이션과-동일합니다" aria-label="Permalink to &quot;3. 명령은 시뮬레이션과 동일합니다&quot;">​</a></h3><ul><li>📝 <em>실제 로봇을 조작하기 전에 먼저 시뮬레이터에서 충분히 연습해 보세요.</em></li></ul><h2 id="로봇-업데이트" tabindex="-1">로봇 업데이트 <a class="header-anchor" href="#로봇-업데이트" aria-label="Permalink to &quot;로봇 업데이트&quot;">​</a></h2><p>로봇 소프트웨어는 앱에서 갱신합니다. <code>소프트웨어 업데이트</code> 화면에서 <strong><code>로봇 소프트웨어 전송</code></strong> 을 누르면 앱이 새 버전을 보내고, 전송이 끝나는 즉시 로봇이 배포한 뒤 재부팅 여부를 묻습니다.</p><p><strong>→ <a href="/RBQ/ko/manual/gui/software-update.html">로봇 소프트웨어 업데이트</a></strong></p><p>앱 자체도 같은 화면의 <code>이 앱</code> 절에서 업데이트합니다.</p><p><strong>→ <a href="/RBQ/ko/manual/gui/software-update.html">앱 업데이트</a></strong></p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>재시작 전에 로봇을 <strong>앉은 자세</strong>로 두고, 재시작이 끝날 때까지 움직이지 마세요. 바이너리와 스크립트 버전이 맞지 않으면 예상치 못한 동작이 생길 수 있습니다.</p></div></div><p><code>scripts/deploy.bash</code>는 로컬 개발용입니다. 방금 빌드한 바이너리를 실행한 PC의 <code>~/rbq_ws/</code>로 복사합니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/deploy.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --local</span></span></code></pre></div><table tabindex="0"><thead><tr><th>인자</th><th>설명</th></tr></thead><tbody><tr><td><code>--help</code></td><td>도움말 메시지를 출력하고 종료</td></tr><tr><td><code>--local</code></td><td>동일 PC의 <code>~/rbq_ws/</code>에 배포</td></tr><tr><td><code>--pro [FILES...]</code></td><td>지정한 바이너리만 배포</td></tr></tbody></table>`,49)])])}const k=s(n,[["render",r]]);export{m as __pageData,k as default};
